let stylesheetReady = null;
let runtimeReady = null;

// Formula markup is generated by Hugo. Previews only need the matching CSS.
export function loadKatexStyles(base) {
  if (stylesheetReady) return stylesheetReady;
  const href = new URL(base + "katex.min.css", document.baseURI).href;
  const loaded = [...document.querySelectorAll('link[rel="stylesheet"]')].some(link => link.href === href && link.sheet);
  if (loaded) return Promise.resolve();
  stylesheetReady = new Promise((resolve, reject) => {
    const link = document.createElement("link");
    link.addEventListener("load", resolve, { once: true });
    link.addEventListener("error", () => {
      link.remove();
      stylesheetReady = null;
      reject(new Error("Math stylesheet failed"));
    }, { once: true });
    link.rel = "stylesheet";
    link.href = href;
    document.head.appendChild(link);
  });
  return stylesheetReady;
}

function loadScript(src) {
  return new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = src;
    script.onload = resolve;
    script.onerror = () => { script.remove(); reject(new Error("Math script failed")); };
    document.head.appendChild(script);
  });
}

// Only raw HTML formulas need the browser compatibility renderer.
export function loadKatexRuntime(base) {
  if (!runtimeReady) {
    runtimeReady = loadKatexStyles(base).then(async () => {
      if (!window.katex) await loadScript(base + "katex.min.js");
      if (!window.renderMathInElement) await loadScript(base + "auto-render.min.js");
    }).catch(error => { runtimeReady = null; throw error; });
  }
  return runtimeReady;
}

export function renderMath(element) {
  window.renderMathInElement(element, {
    delimiters: [
      { left: "$$", right: "$$", display: true },
      { left: "\\(", right: "\\)", display: false },
      { left: "\\[", right: "\\]", display: true },
      { left: "$", right: "$", display: false },
    ],
    ignoredClasses: ["katex"],
    throwOnError: false,
  });
}
